impl BlockSimulator {
    fn new() -> Self {
        use BlockSymbol::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R, s1, s1, s3],
            state: HigherState::RightC,
            base_steps: 12,
            self_steps: 0,
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }
}

#[derive(Clone, Copy, PartialEq)]
enum RightSymbol {
    R,
    S1,
    S3,
}

impl RightSymbol {
    fn to_block_symbol(&self) -> BlockSymbol {
        match self {
            RightSymbol::S1 => BlockSymbol::s1,
            RightSymbol::S3 => BlockSymbol::s3,
            RightSymbol::R => BlockSymbol::R,
        }
    }
}

struct InfHeadCycleSim {
    x: Exp,
    y: Exp,
    n_cells: usize,
    rtape: Vec<RightSymbol>,
}

impl InfHeadCycleSim {
    fn new() -> Self {
        use RightSymbol::*;
        Self {
            x: 0,
            y: 0,
            n_cells: 0,
            rtape: vec![R, S1, S1, S3],
        }
    }

    fn step(&mut self) -> bool {
        use RightSymbol::*;
        match (self.x % 2, self.y % 2, self.rtape.last()) {
            (0, 0, Some(S3)) => {
                self.x = self.x / 2 + 1;
                self.y += self.x;
                self.rtape.pop();
                self.n_cells += 1;
                false
            }
            (0, 0, Some(S1)) => {
                self.y /= 2;
                self.x += self.y + 2;
                self.rtape.pop();
                self.n_cells += 1;
                false
            }
            (1, 1, Some(S3)) => {
                self.y /= 2;
                self.x += self.y + 3;
                self.rtape.pop();
                self.n_cells += 1;
                false
            }
            (1, 1, Some(S1)) => {
                self.x = self.x / 2 + 1;
                self.y += self.x + 1;
                self.rtape.pop();
                self.n_cells += 1;
                false
            }
            (_, _, Some(R)) if self.y == 0 => true,
            (_, _, Some(R)) => {
                self.x += 1;
                self.y -= 1;
                self.rtape.extend_from_slice(&[S1, S3]);
                false
            }
            _ => unimplemented!(),
        }
    }
}

