#[derive(Clone, Copy)]
enum LongHead {
    B(u32),
    C,
    BCB { left: u32, right: u32, exp2: u32 },
}

impl fmt::Display for LongHead {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LongHead::B(n) => {
                assert!(*n > 0);
                write!(f, "b")?;
                if *n > 1 {
                    write!(f, "^{n}")?;
                }
            }
            LongHead::C => write!(f, "c")?,
            LongHead::BCB { left, right, exp2 } => {
                write!(f, "({left},{right})")?;
                match exp2 {
                    0 => (),
                    1 => write!(f, "^2")?,
                    2.. => write!(f, "^2^{exp2}")?,
                }
            }
        }
        Ok(())
    }
}

#[derive(Clone, Copy)]
enum LongTerm {
    Symbol(RightSymbol),
    Head(LongHead),
}

#[derive(Debug, Clone, PartialEq)]
pub enum LongSimError {
    Heck,
    OutOfHeads,
    UndefinedTransition,
}

impl fmt::Display for LongSimError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Heck => write!(f, "Heck"),
            Self::OutOfHeads => write!(f, "Out of heads"),
            Self::UndefinedTransition => write!(f, "Undefined transition"),
        }
    }
}

#[derive(Clone)]
struct LongSim {
    /// In other longitudinal simulations, the near_tape is a VecDeque, but a Vec suffices here
    near_tape: Vec<LongTerm>,
    end_tape: Vec<RightSymbol>,
    n_heads: Exp,
    base_steps: Exp,
    self_steps: u64,
}

impl fmt::Display for LongSim {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use colored::*;
        write!(
            f,
            "{} | {} | {}: ",
            self.self_steps, self.n_heads, self.base_steps
        )?;

        for x in &self.near_tape {
            match x {
                LongTerm::Head(h) => {
                    let s0 = format!("{h} ");
                    write!(f, "{}", s0.red().bold())?;
                }
                LongTerm::Symbol(s) => {
                    write!(f, "{s}")?;
                }
            }
        }

        for s in self.end_tape.iter().rev() {
            write!(f, "{s}")?;
        }
        Ok(())
    }
}

impl LongSim {
    fn new() -> Self {
        use RightSymbol::*;
        Self {
            near_tape: Vec::new(),
            end_tape: vec![R, S1, S1, S3],
            n_heads: 0,
            base_steps: 12,
            self_steps: 0,
        }
    }

    fn basic_step(&mut self) -> Result<Exp, LongSimError> {
        use LongHead::*;
        use LongTerm as L;
        use RightSymbol::*;
        let n_steps = match (self.near_tape.pop(), self.end_tape.pop()) {
            (Some(L::Head(h)), Some(s)) => match (h, s) {
                // b^2k 1 -> 1 b^k (3k)
                // b^2k 3 -> 3 b^k (3k)
                (B(n), s @ (S1 | S3)) if n >= 2 && n % 2 == 0 => {
                    let k = n / 2;
                    self.near_tape.push(L::Symbol(s));
                    self.near_tape.push(L::Head(B(k)));
                    k as Exp * 3
                }
                // b^2k+1 1 -> 3 b^k+1 (3k+2)
                (B(n), S1) if n % 2 == 1 => {
                    let k = n / 2;
                    self.near_tape.push(L::Symbol(S3));
                    self.near_tape.push(L::Head(B(k + 1)));
                    k as Exp * 3 + 2
                }
                // b^2k+1 3 -> 1 b^k (3k+1)
                (B(n), S3) if n % 2 == 1 => {
                    let k = n / 2;
                    if k > 0 {
                        self.near_tape.push(L::Symbol(S1));
                        self.near_tape.push(L::Head(B(k)));
                    } else {
                        self.end_tape.push(S1);
                    }
                    k as Exp * 3 + 1
                }
                // c 1 -> 3 bc (3)
                (C, S1) => {
                    self.near_tape
                        .extend_from_slice(&[L::Symbol(S3), L::Head(B(1)), L::Head(C)]);
                    3
                }
                // c 3 -> 1 b (2)
                (C, S3) => {
                    self.near_tape.push(L::Symbol(S1));
                    self.near_tape.push(L::Head(B(1)));
                    2
                }
                // b $ -> 31$ (7)
                (B(n), R) => {
                    self.end_tape.extend_from_slice(&[R, S1, S3]);
                    if n > 1 {
                        self.near_tape.push(L::Head(B(n - 1)));
                    }
                    7
                }
                // c $ -> heck
                (C, R) => return Err(LongSimError::Heck),
                // (x, y)^2^0 = b^x c b^y
                (
                    BCB {
                        left: x,
                        right: y,
                        exp2: 0,
                    },
                    s,
                ) => {
                    self.end_tape.push(s);
                    if x > 0 {
                        self.near_tape.push(L::Head(B(x)));
                    }
                    self.near_tape.push(L::Head(C));
                    if y > 0 {
                        self.near_tape.push(L::Head(B(y)));
                    }
                    0
                }
                // (2r, 2s)^2^(n+1) 3 -> 3 (r+1, r+2s+1)^2^n ((6r + 6s + 5) * 2^n)
                // (2r, 2s)^2^(n+1) 1 -> 1 (2r+s+2, s)^2^n   ((6r + 6s + 5) * 2^n)
                (
                    BCB {
                        left: x,
                        right: y,
                        exp2: exp @ 1..,
                    },
                    symb @ (S1 | S3),
                ) if x % 2 == 0 && y % 2 == 0 => {
                    let r = x / 2;
                    let s = y / 2;
                    let n = exp - 1;
                    let new_head = if symb == S3 {
                        BCB {
                            left: r + 1,
                            right: r + 2 * s + 1,
                            exp2: n,
                        }
                    } else {
                        BCB {
                            left: 2 * r + s + 2,
                            right: s,
                            exp2: n,
                        }
                    };
                    self.near_tape.push(L::Symbol(symb));
                    self.near_tape.push(L::Head(new_head));
                    (6 * (r + s) + 5) as Exp * (1 << n)
                }
                // (2r+1, 2s+1)^2^(n+1) 3 -> 3 (2r+s+4, s)^2^n   ((6r + 6s + 11) * 2^n)
                // (2r+1, 2s+1)^2^(n+1) 1 -> 1 (r+1, r+2s+3)^2^n ((6r + 6s + 11) * 2^n)
                (
                    BCB {
                        left: x,
                        right: y,
                        exp2: exp @ 1..,
                    },
                    symb @ (S1 | S3),
                ) if x % 2 == 1 && y % 2 == 1 => {
                    let r = x / 2;
                    let s = y / 2;
                    let n = exp - 1;
                    let new_head = if symb == S3 {
                        BCB {
                            left: 2 * r + s + 4,
                            right: s,
                            exp2: n,
                        }
                    } else {
                        BCB {
                            left: r + 1,
                            right: r + 2 * s + 3,
                            exp2: n,
                        }
                    };
                    self.near_tape.push(L::Symbol(symb));
                    self.near_tape.push(L::Head(new_head));
                    (6 * (r + s) + 11) as Exp * (1 << n)
                }
                _ => return Err(LongSimError::UndefinedTransition),
            },
            (Some(L::Symbol(left)), Some(right)) => {
                self.end_tape.push(right);
                self.end_tape.push(left);
                while let Some(L::Symbol(s)) = self.near_tape.last() {
                    self.end_tape.push(*s);
                    self.near_tape.pop();
                }
                0
            }
            (None, Some(s)) => {
                self.end_tape.push(s);
                return Err(LongSimError::OutOfHeads);
            }
            _ => return Err(LongSimError::UndefinedTransition),
        };
        Ok(n_steps)
    }

    fn step(&mut self) -> Result<(), LongSimError> {
        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    fn add_heads(&mut self, exp2: u32) {
        use LongHead::*;
        assert!(self.near_tape.is_empty());
        self.base_steps += 1 << exp2;
        self.n_heads += 1 << exp2;
        if exp2 == 0 {
            self.near_tape.push(LongTerm::Head(C));
        } else {
            self.near_tape.push(LongTerm::Head(BCB {
                left: 0,
                right: 0,
                exp2,
            }));
        }
    }
}

fn run_inf_head_cycle_sim() {
    let mut sim = InfHeadCycleSim::new();
    println!("{sim}");
    loop {
        let halted = sim.step();
        println!("{sim}");
        if halted {
            break;
        }
    }
}

fn run_block_sim() {
    let mut sim = BlockSimulator::new();
    println!("{sim}");
    for k in 1..=10000 {
        let res = sim.step();
        println!("{sim}");
        if res.is_err() {
            println!("{res:?}");
            break;
        }
    }
}

fn main() {
    // run_inf_head_cycle_sim();
    // run_block_sim();

    let mut sim = LongSim::new();
    let mut backup: Option<(LongSim, u32)> = None;
    let mut ps_add: Vec<u32> = Vec::new();

    println!("{sim}");
    'outer: loop {
        loop {
            let res = sim.step();
            // println!("{sim}");
            if let Err(e) = res {
                println!("{e}");
                match e {
                    LongSimError::OutOfHeads => {
                        let p_add = sim.end_tape.len() as u32 - 1;
                        println!("add {} heads", 1u128 << p_add);
                        backup = Some((sim.clone(), p_add));
                        sim.add_heads(p_add);
                        ps_add.push(p_add);
                        println!("{sim}");
                        break;
                    }
                    LongSimError::Heck => {
                        // We must have previously added too many heads, try again with fewer heads
                        println!("restoring from backup");
                        if let Some((b, old_p_add)) = &backup {
                            sim = b.clone();
                            ps_add.pop().unwrap();
                            println!("{sim}");

                            if sim.end_tape[1..].iter().all(|&s| s == RightSymbol::S1) {
                                println!("switching to direct sim");
                                break 'outer;
                            }

                            let p_add = old_p_add - 1;
                            backup = Some((sim.clone(), p_add));
                            println!("add {} heads", 1u128 << p_add);
                            sim.add_heads(p_add);
                            ps_add.push(p_add);
                            println!("{sim}");
                        } else {
                            unimplemented!();
                        }
                    }
                    _ => panic!(),
                }
            }
        }
    }

    let n_heads_total = sim.n_heads;
    let mut n_left = n_heads_total;
    let mut ps_add_alt: Vec<u32> = Vec::new();
    while n_left > 0 {
        let p = n_left.ilog2();
        ps_add_alt.push(p);
        n_left -= 1 << p;
    }

    {
        use BlockSymbol::*;
        let mut direct_sim = BlockSimulator {
            left_tape: vec![L],
            right_tape: sim.end_tape.iter().map(|s| s.to_block_symbol()).collect(),
            state: HigherState::RightC,
            base_steps: sim.base_steps,
            self_steps: 0,
        };
        println!("{direct_sim}");
        loop {
            let res = direct_sim.step();
            println!("{direct_sim}");
            if let Err(e) = res {
                println!("{e}");
                break;
            }
        }
    }

    for (i, p) in ps_add.iter().enumerate() {
        if i > 0 {
            print!(", ");
        }
        print!("{p}");
    }
    println!();

    for (i, p) in ps_add_alt.iter().enumerate() {
        if i > 0 {
            print!(", ");
        }
        print!("{p}");
    }
    println!();

    // re-run the long. simulation except now we know enough that we shouldn't need to backtrack
    let mut sim = LongSim::new();
    println!("{sim}");

    for p_add in ps_add_alt.iter().rev() {
        sim.add_heads(*p_add);
        println!("{sim}");

        loop {
            let res = sim.step();
            // println!("{sim}");
            if let Err(e) = res {
                match e {
                    LongSimError::OutOfHeads => {
                        println!("{sim}");
                        break;
                    }
                    _ => panic!("{e}"),
                }
            }
        }
    }
}
